  Future<void> setup() async { setState(() { busy = true; error = null; }); try { final google = password.text.isEmpty ? await googleReauth() : null; final s = await widget.api.startMfaSetup(password: password.text.isEmpty ? null : password.text, googleIdToken: google, code: code.text.trim().isEmpty ? null : code.text.trim()); if (mounted) setState(() { setupChallenge = s['setup_challenge']; uri = s['otpauth_uri']; code.clear(); password.clear(); }); } catch (_) { if (mounted) setState(() => error = 'Najpierw potwierdź tożsamość hasłem lub Google oraz aktualnym kodem 2FA, jeśli jest włączone.'); } finally { if (mounted) setState(() => busy = false); } }
