  Future<void> removePasskey(Map<String, dynamic> key) async { final ok = await showDialog<bool>(context: context, builder: (_) => AlertDialog(title: const Text('Usunąć klucz dostępu?'), content: const Text('Potwierdź tożsamość hasłem lub Google oraz kodem 2FA/odzyskiwania.'), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Anuluj')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Usuń'))])); if (ok != true) return; setState(() { busy = true; error = null; }); try { final googleIdToken = password.text.isEmpty ? await googleReauth() : null; await widget.api.deletePasskey(key['id'] as int, password: password.text.isEmpty ? null : password.text, googleIdToken: googleIdToken, code: code.text.trim()); await refreshPasskeys(); } catch (_) { if (mounted) setState(() => error = 'Nie można usunąć tego klucza dostępu. Potwierdź tożsamość lub zachowaj inną metodę logowania.'); } finally { if (mounted) setState(() => busy = false); } }
